/* 01 — Christmas Gift Ribbon Reveal
   Christmas Sale Promotion | 25 seconds | 2 scenes | seamless loop
   UHD 3840 x 2160 reference; scales to 1920 x 1080 / 2560 x 1440.
   Time Motion Studio: time is already seconds.
   Pure Canvas 2D, solid colors, no external assets or glow.
   Video export bitrate must be set separately to 100 Mbps. */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const C = {
  "bg": "#F4F0E6",
  "ink": "#183D34",
  "paper": "#FFFCF4",
  "green": "#2B6751",
  "red": "#B93743",
  "gold": "#DBB76A",
  "line": "#D6DDD1",
  "deep": "#214D40",
  "soft": "#E6ECE3"
};
  // All helpers are local to draw; no assets, browser globals, or dependencies.
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { const q = clamp(v); return q*q*q*(q*(q*6-15)+10); };
  const lerp = (a, b, v) => a + (b-a)*v;
  const pulse = (v, a, b, c, d) => ease((v-a)/(b-a)) * (1-ease((v-c)/(d-c)));
  // Both transitions end before a scene boundary. Their first two derivatives
  // are zero at each endpoint; the 25-second seam has matching periodic motion.
  const mix = currentScene === 0
    ? ease((sceneProgress-0.76)/0.22)
    : 1-ease((sceneProgress-0.76)/0.22);
  const firstAlpha = 1-ease(mix/0.47);
  const secondAlpha = ease((mix-0.53)/0.47);
  const scale = Math.min(width/1920, minSide/1080);
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.setLineDash([]);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width-1920*scale)/2, (height-1080*scale)/2);
  ctx.scale(scale, scale);

  function alpha(value, paint) {
    if (value <= 0.00001) return;
    ctx.save(); ctx.globalAlpha *= clamp(value); paint(); ctx.restore();
  }
  function path(points, fill, stroke, lw = 2) {
    ctx.beginPath();
    points.forEach((p,i) => i ? ctx.lineTo(p[0],p[1]) : ctx.moveTo(p[0],p[1]));
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.lineJoin='round'; ctx.stroke(); }
  }
  function box(x,y,w,h,r,fill,stroke,lw=2) {
    if (w<=0 || h<=0) return;
    r = Math.min(r,w/2,h/2);
    ctx.beginPath(); ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r); ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h); ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r); ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
    if (fill) { ctx.fillStyle=fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle=stroke; ctx.lineWidth=lw; ctx.lineJoin='round'; ctx.stroke(); }
  }
  function circle(x,y,r,fill,stroke,lw=2) {
    ctx.beginPath(); ctx.arc(x,y,r,0,TAU);
    if (fill) {ctx.fillStyle=fill;ctx.fill();}
    if (stroke) {ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function ellipse(x,y,rx,ry,fill,rotation=0) {
    ctx.beginPath();ctx.ellipse(x,y,rx,ry,rotation,0,TAU);ctx.fillStyle=fill;ctx.fill();
  }
  function line(x1,y1,x2,y2,color,lw=2) {
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
    ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.lineCap='round';ctx.stroke();
  }
  function text(str,x,y,size,color=C.ink,weight=700,align='left',maxWidth=1000,maxHeight=size*1.15) {
    // Fit the measured glyphs. Never compress text horizontally.
    ctx.textAlign=align;ctx.textBaseline='alphabetic';
    ctx.font=weight+' '+size+'px Arial, Helvetica, "DejaVu Sans", sans-serif';
    let m=ctx.measureText(str);
    let a=m.actualBoundingBoxAscent || size*0.74;
    let d=m.actualBoundingBoxDescent || size*0.20;
    const ratio=Math.min(1,maxWidth/Math.max(1,m.width),maxHeight/Math.max(1,a+d));
    if (ratio<1) {
      size*=ratio;ctx.font=weight+' '+size+'px Arial, Helvetica, "DejaVu Sans", sans-serif';
      m=ctx.measureText(str);a=m.actualBoundingBoxAscent || size*0.74;d=m.actualBoundingBoxDescent || size*0.20;
    }
    ctx.fillStyle=color;ctx.fillText(str,x,y+(a-d)/2);
  }
  function caps(str,x,y,maxWidth=740,color=C.ink,size=18,align='left') {
    text(str,x,y,size,color,700,align,maxWidth,size*1.1);
  }
  function heading(lines,x,y,size,maxWidth=780,color=C.ink,align='left',leading=1.1) {
    lines.forEach((s,i)=>text(s,x,y+i*size*leading,size,color,800,align,maxWidth,size));
  }
  function pill(x,y,w,h,str,fill=C.ink,color=C.paper) {
    box(x,y,w,h,h/2,fill);text(str,x+w/2,y+h/2,18,color,700,'center',w-36,h-18);
  }
  function star(x,y,r,fill,angle=-Math.PI/2,inner=0.43) {
    const p=[];for(let i=0;i<10;i++){const a=angle+i*Math.PI/5;const q=i%2?r*inner:r;p.push([x+Math.cos(a)*q,y+Math.sin(a)*q]);}
    path(p,fill);
  }
  function snowflake(x,y,r,color,lw=3,angle=0) {
    ctx.save();ctx.translate(x,y);ctx.rotate(angle);
    for(let i=0;i<6;i++) {
      const a=i*Math.PI/3,dx=Math.cos(a),dy=Math.sin(a);
      line(0,0,dx*r,dy*r,color,lw);
      for(const sign of [-1,1]) {
        const b=a+sign*Math.PI/3;
        line(dx*r*0.61,dy*r*0.61,dx*r*0.61-Math.cos(b)*r*0.24,dy*r*0.61-Math.sin(b)*r*0.24,color,lw);
      }
    }
    ctx.restore();
  }
  function pine(x,y,w,h,color=C.green) {
    box(x-w*0.06,y-h*0.16,w*0.12,h*0.16,3,C.ink);
    const top=y-h;
    path([[x,top],[x+w*.23,top+h*.29],[x+w*.12,top+h*.29],
      [x+w*.37,top+h*.56],[x+w*.23,top+h*.56],[x+w*.5,top+h*.87],
      [x-w*.5,top+h*.87],[x-w*.23,top+h*.56],[x-w*.37,top+h*.56],
      [x-w*.12,top+h*.29],[x-w*.23,top+h*.29]],color);
  }
  function leaf(x,y,length,width,color,angle) {
    ctx.save();ctx.translate(x,y);ctx.rotate(angle);
    ctx.beginPath();ctx.moveTo(0,0);ctx.bezierCurveTo(length*.35,-width,length*.8,-width,length,0);
    ctx.bezierCurveTo(length*.8,width,length*.35,width,0,0);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.restore();
  }
  function sprig(x,y,length,color,angle=0) {
    ctx.save();ctx.translate(x,y);ctx.rotate(angle);
    line(0,0,length,0,color,3);
    for(let i=1;i<=5;i++) {
      const q=length*i/6;
      leaf(q,0,length*.31,length*.068,color,-.7);
      leaf(q,0,length*.31,length*.068,color,.7);
    }
    ctx.restore();
  }
  function wreath(x,y,r,rotation=0) {
    ctx.save();ctx.translate(x,y);ctx.rotate(rotation);
    circle(0,0,r,null,C.green,r*.10);
    for(let i=0;i<24;i++) {
      const a=i*TAU/24;
      sprig(Math.cos(a)*r,Math.sin(a)*r,r*.34,i%2?C.green:C.deep,a+Math.PI/2-.32);
      if(i%4===0) {
        circle(Math.cos(a)*(r-4),Math.sin(a)*(r-4),r*.025,C.red);
        circle(Math.cos(a+.045)*(r+7),Math.sin(a+.045)*(r+7),r*.021,C.red);
      }
    }
    ctx.restore();
  }
  function bow(x,y,w,color) {
    ctx.beginPath();ctx.moveTo(x,y);
    ctx.bezierCurveTo(x-w*.4,y-w*.44,x-w*.6,y-w*.05,x-w*.29,y+w*.035);
    ctx.bezierCurveTo(x-w*.17,y+w*.06,x-w*.08,y+w*.03,x,y);ctx.closePath();ctx.fillStyle=color;ctx.fill();
    ctx.beginPath();ctx.moveTo(x,y);
    ctx.bezierCurveTo(x+w*.4,y-w*.44,x+w*.6,y-w*.05,x+w*.29,y+w*.035);
    ctx.bezierCurveTo(x+w*.17,y+w*.06,x+w*.08,y+w*.03,x,y);ctx.closePath();ctx.fill();
    circle(x,y,w*.075,color);
  }
  function gift(x,y,w,h,body=C.red,ribbon=C.gold,lift=0) {
    box(x-w/2,y-h,w,h,8,body);
    box(x-w*.075,y-h,w*.15,h,0,ribbon);
    // Lid, lid ribbon, and bow use the same parent anchor.
    const ly=y-h-18-lift;
    box(x-w/2-9,ly,w+18,30,6,body);
    box(x-w*.075,ly,w*.15,30,0,ribbon);
    bow(x,ly-3,w*.46,ribbon);
    line(x-w*.5+20,y-18,x-w*.20,y-18,ribbon,3);
  }
  function tag(x,y,w,h,fill,str,color=C.paper,rotation=0) {
    ctx.save();ctx.translate(x,y);ctx.rotate(rotation);
    path([[-w/2+18,-h/2],[w/2,-h/2],[w/2,h/2],[-w/2+18,h/2],[-w/2,0]],fill);
    circle(-w/2+18,0,4,C.paper);
    text(str,9,0,h*.38,color,800,'center',w-52,h*.6);
    ctx.restore();
  }
  function bag(x,y,w,h,color=C.red,style=0) {
    const top=y-h;
    path([[x-w*.40,top+10],[x-w*.43,top-20],[x-w*.16,top-37],[x+w*.06,top-15],[x+w*.24,top-36],[x+w*.43,top+6]],C.paper);
    box(x-w/2,top,w,h,10,color);
    box(x-w/2+12,top+h-20,w-24,4,2,C.paper);
    ctx.beginPath();ctx.moveTo(x-w*.23,top+27);
    ctx.bezierCurveTo(x-w*.23,top-62,x+w*.23,top-62,x+w*.23,top+27);
    ctx.strokeStyle=C.ink;ctx.lineWidth=7;ctx.lineCap='round';ctx.stroke();
    circle(x-w*.23,top+27,5,C.ink);circle(x+w*.23,top+27,5,C.ink);
    if(style%3===0) snowflake(x,top+h*.58,w*.21,C.paper,4);
    if(style%3===1) {star(x,top+h*.57,w*.22,C.paper);circle(x,top+h*.57,w*.33,null,C.paper,2);}
    if(style%3===2) {pine(x,top+h*.76,w*.38,h*.39,C.paper);}
  }
  function ornament(x,top,length,r,color,style=0,angle=0) {
    ctx.save();ctx.translate(x,top);ctx.rotate(angle);
    line(0,0,0,length-r-14,C.ink,2);
    box(-11,length-r-14,22,17,4,C.gold);
    circle(0,length,r,color);
    ctx.save();ctx.beginPath();ctx.arc(0,length,r-3,0,TAU);ctx.clip();
    if(style%3===0) {
      for(let i=-2;i<=2;i++) line(-r,length+i*r*.33,r,length+i*r*.33,C.paper,6);
    } else if(style%3===1) {
      snowflake(0,length,r*.57,C.paper,4);
    } else {
      for(let row=-1;row<=1;row++) for(let col=-1;col<=1;col++) circle(col*r*.49,length+row*r*.43,4,C.paper);
    }
    ctx.restore();ctx.restore();
  }
  function stocking(x,y,size,color,pattern=0,angle=0) {
    ctx.save();ctx.translate(x,y);ctx.scale(size,size);
    // Rotate around the fixed hanger point, not the center of the cuff.
    ctx.translate(-24,-29);ctx.rotate(angle);ctx.translate(24,29);
    ctx.beginPath();ctx.moveTo(-43,0);ctx.lineTo(43,0);ctx.lineTo(43,137);
    ctx.bezierCurveTo(43,151,72,159,97,169);ctx.bezierCurveTo(130,181,130,219,98,229);
    ctx.lineTo(-13,229);ctx.bezierCurveTo(-42,229,-50,208,-45,182);ctx.lineTo(-43,0);ctx.closePath();ctx.fillStyle=color;ctx.fill();
    box(-50,-6,100,38,8,C.paper);
    line(-24,-7,-24,-29,C.ink,4);line(-24,-29,-12,-29,C.ink,4);
    if(pattern%2===0) snowflake(-2,94,24,C.paper,4);
    else {star(-2,95,24,C.paper);line(-28,54,28,54,C.paper,4);line(-29,140,29,140,C.paper,4);}
    path([[60,178],[96,183],[104,199],[96,216],[60,216]],C.deep);
    ctx.restore();
  }
  function coupon(x,y,w,h,fill=C.paper) {
    box(x-w/2,y-h/2,w,h,14,fill,C.ink,2);
    ctx.save();ctx.setLineDash([6,8]);line(x-w/2+53,y-h/2+18,x-w/2+53,y+h/2-18,C.line,2);ctx.restore();
    circle(x-w/2+53,y-h/2,10,C.bg);
    circle(x-w/2+53,y+h/2,10,C.bg);
  }
  function cart(x,y,s,color=C.ink) {
    ctx.save();ctx.translate(x,y);ctx.scale(s,s);
    line(-52,-35,-38,-35,color,5);line(-38,-35,-24,17,color,5);
    path([[-34,-24],[47,-24],[35,9],[-25,9]],null,color,5);
    line(-24,17,37,17,color,5);circle(-16,30,6,color);circle(27,30,6,color);ctx.restore();
  }
  function sceneCopy(first,second,x=120,y=305,size=100,maxWidth=770,leading=1.12) {
    alpha(firstAlpha,()=>heading(first,x,y,size,maxWidth,C.ink,'left',leading));
    alpha(secondAlpha,()=>heading(second,x,y,size,maxWidth,C.ink,'left',leading));
  }
  function discount(x,y,value,size=164,maxWidth=650,color=C.red) {
    caps('UP TO',x,y-size*.59,maxWidth,C.ink,22);
    text(value,x,y,size,color,800,'left',maxWidth,size);
    caps('OFF SELECTED CHRISTMAS GIFTS',x,y+size*.62,maxWidth,C.ink,21);
  }
  function frame() {
    box(58,58,1804,964,28,null,C.line,2);
    line(112,132,160,132,C.red,5);
    caps('CHRISTMAS / HOLIDAY OFFERS',180,132,700,C.ink,18);
    caps('THE SEASON OF GIVING',1808,948,500,C.ink,17,'right');
  }
  function accent(x,y,r=18,offset=0,color=C.gold) {
    ctx.save();ctx.translate(x,y+5*Math.sin(phase*2+offset));ctx.rotate(.045*Math.sin(phase+offset));star(0,0,r,color);ctx.restore();
  }
  function snowySky(x,y,w,h,count=18) {
    for(let i=0;i<count;i++) {
      const f=(loopT/duration+(i*0.61803398875)%1)%1;
      const xx=x+30+((i*173)%Math.max(1,w-60))+8*Math.sin(phase+i);
      const yy=y+h*f;
      alpha(Math.sin(Math.PI*f)**2*.65,()=>circle(xx,yy,3+(i%3),C.paper));
    }
  }
  frame();

  caps('GIFTS & FESTIVE SAVINGS',120,221,780,C.green,22);
  alpha(firstAlpha,()=>{
    heading(['CHRISTMAS','SALE'],120,334,116,800);
    text('Gifts worth giving.',124,614,29,C.ink,400,'left',740);
    text('Savings worth sharing.',124,659,29,C.ink,400,'left',740);
    pill(120,742,294,54,'THE HOLIDAY EDIT',C.green);
  });
  alpha(secondAlpha,()=>{
    box(108,279,788,494,26,C.paper,C.line,2);
    pill(138,310,286,48,'CHRISTMAS SPECIAL',C.green);
    discount(140,512,'50%',174,690);
    line(140,704,838,704,C.line,2);
    caps('A LITTLE MORE JOY. A LITTLE LESS TO SPEND.',140,740,690,C.ink,18);
  });
  const open=currentScene===0 ? pulse(sceneProgress,.10,.28,.53,.69) : 0;
  box(1012,832,763,14,7,C.line);
  pine(1640,445,115,215,C.green);
  star(1640,216,19,C.gold);
  gift(1110,815,170,178,C.green,C.paper,0);
  gift(1400,815,254,222,C.red,C.gold,open*65);
  gift(1690,815,168,163,C.gold,C.red,0);
  const labelY=370+5*Math.sin(phase*2);
  const tagAngle=.025*Math.sin(phase*2);
  const holeX=1375.5,localHole=-74.5;
  line(holeX,205,holeX,labelY,C.ink,2);
  tag(holeX-localHole*Math.cos(tagAngle),labelY-localHole*Math.sin(tagAngle),185,74,C.green,'SALE',C.paper,tagAngle);
  accent(1080,308,24,.4);
  accent(1790,538,19,1.5,C.red);
  snowflake(1160,548,22,C.line,3,.05*Math.sin(phase));
  ctx.restore();
}

/* 02 — Hanging Ornament Offer Gallery
   Christmas Sale Promotion | 25 seconds | 2 scenes | seamless loop
   UHD 3840 x 2160 reference; scales to 1920 x 1080 / 2560 x 1440.
   Time Motion Studio: time is already seconds.
   Pure Canvas 2D, solid colors, no external assets or glow.
   Video export bitrate must be set separately to 100 Mbps. */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 2;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const C = {
  "bg": "#EDF0ED",
  "ink": "#1B3342",
  "paper": "#FFFBF2",
  "green": "#36735F",
  "red": "#B64C50",
  "gold": "#D4AD6B",
  "line": "#CDD7D4",
  "deep": "#244F45",
  "soft": "#E2E8E0"
};
  // All helpers are local to draw; no assets, browser globals, or dependencies.
  const TAU = Math.PI * 2;
  const phase = TAU * loopT / duration;
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { const q = clamp(v); return q*q*q*(q*(q*6-15)+10); };
  const lerp = (a, b, v) => a + (b-a)*v;
  const pulse = (v, a, b, c, d) => ease((v-a)/(b-a)) * (1-ease((v-c)/(d-c)));
  // Both transitions end before a scene boundary. Their first two derivatives
  // are zero at each endpoint; the 25-second seam has matching periodic motion.
  const mix = currentScene === 0
    ? ease((sceneProgress-0.76)/0.22)
    : 1-ease((sceneProgress-0.76)/0.22);
  const firstAlpha = 1-ease(mix/0.47);
  const secondAlpha = ease((mix-0.53)/0.47);
  const scale = Math.min(width/1920, minSide/1080);
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.setLineDash([]);
  ctx.fillStyle = C.bg;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width-1920*scale)/2, (height-1080*scale)/2);
  ctx.scale(scale, scale);

  function alpha(value, paint) {
    if (value <= 0.00001) return;
    ctx.save(); ctx.globalAlpha *= clamp(value); paint(); ctx.restore();
  }
  function path(points, fill, stroke, lw = 2) {
    ctx.beginPath();
    points.forEach((p,i) => i ? ctx.lineTo(p[0],p[1]) : ctx.moveTo(p[0],p[1]));
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.lineJoin='round'; ctx.stroke(); }
  }
  function box(x,y,w,h,r,fill,stroke,lw=2) {
    if (w<=0 || h<=0) return;
    r = Math.min(r,w/2,h/2);
    ctx.beginPath(); ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r); ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h); ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r); ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
    if (fill) { ctx.fillStyle=fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle=stroke; ctx.lineWidth=lw; ctx.lineJoin='round'; ctx.stroke(); }
  }
  function circle(x,y,r,fill,stroke,lw=2) {
    ctx.beginPath(); ctx.arc(x,y,r,0,TAU);
    if (fill) {ctx.fillStyle=fill;ctx.fill();}
    if (stroke) {ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function ellipse(x,y,rx,ry,fill,rotation=0) {
    ctx.beginPath();ctx.ellipse(x,y,rx,ry,rotation,0,TAU);ctx.fillStyle=fill;ctx.fill();
  }
  function line(x1,y1,x2,y2,color,lw=2) {
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
    ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.lineCap='round';ctx.stroke();
  }
  function text(str,x,y,size,color=C.ink,weight=700,align='left',maxWidth=1000,maxHeight=size*1.15) {
    // Fit the measured glyphs. Never compress text horizontally.
    ctx.textAlign=align;ctx.textBaseline='alphabetic';
