  function sceneCopy(first,second,x=120,y=305,size=100,maxWidth=770,leading=1.12) {
    alpha(firstAlpha,()=>heading(first,x,y,size,maxWidth,C.ink,'left',leading));
    alpha(secondAlpha,()=>heading(second,x,y,size,maxWidth,C.ink,'left',leading));
  }
  function discount(x,y,value,size=164,maxWidth=650,color=C.red) {
    caps('UP TO',x,y-size*.59,maxWidth,C.ink,22);
    text(value,x,y,size,color,800,'left',maxWidth,size);
    caps('OFF SELECTED CHRISTMAS GIFTS',x,y+size*.62,maxWidth,C.ink,21);
  }
  function frame() {
    box(58,58,1804,964,28,null,C.line,2);
    line(112,132,160,132,C.red,5);
    caps('CHRISTMAS / HOLIDAY OFFERS',180,132,700,C.ink,18);
    caps('THE SEASON OF GIVING',1808,948,500,C.ink,17,'right');
  }
  function accent(x,y,r=18,offset=0,color=C.gold) {
    ctx.save();ctx.translate(x,y+5*Math.sin(phase*2+offset));ctx.rotate(.045*Math.sin(phase+offset));star(0,0,r,color);ctx.restore();
  }
  function snowySky(x,y,w,h,count=18) {
    for(let i=0;i<count;i++) {
      const f=(loopT/duration+(i*0.61803398875)%1)%1;
      const xx=x+30+((i*173)%Math.max(1,w-60))+8*Math.sin(phase+i);
      const yy=y+h*f;
      alpha(Math.sin(Math.PI*f)**2*.65,()=>circle(xx,yy,3+(i%3),C.paper));
    }
  }
  frame();

  caps('THE CHRISTMAS ADVENT EDIT',120,229,780,C.green,22);
  alpha(firstAlpha,()=>{
    heading(['24 DAYS.','MORE JOY.'],120,352,104,780);
    text('Discover a new festive offer every day.',124,619,28,C.ink,400,'left',754);
    pill(120,718,331,54,'24 DAYS OF CHRISTMAS DEALS',C.red);
  });
  alpha(secondAlpha,()=>{
    heading(['DAILY','CHRISTMAS','DEALS'],120,328,92,780);
    text('A little surprise for the season of giving.',124,688,28,C.ink,400,'left',765);
    pill(120,782,332,54,'TODAY\'S SPECIAL OFFER',C.green);
  });
  const gridX=971,gridY=285,tw=118,th=114,gx=16,gy=17;
  const focus=14;
  const gridAlpha=1-ease(mix/.32);
  alpha(gridAlpha,()=>{
    for(let i=0;i<24;i++) {
      if(i===focus)continue;
      const x=gridX+(i%6)*(tw+gx),y=gridY+Math.floor(i/6)*(th+gy);
      box(x,y,tw,th,12,C.paper,C.line,2);
      let opening=0;
      const selected=[2,7,19].indexOf(i);
      if(selected>=0 && currentScene===0) {
        const a=.07+selected*.19;
        opening=pulse(sceneProgress,a,a+.075,a+.115,a+.175);
      }
      if(opening>0) {
        if(i===7)gift(x+59,y+83,40,42,C.red,C.gold);
        else star(x+59,y+57,23,i===2?C.gold:C.green);
      }
      // Door flap deliberately reveals the compartment; all surrounding
      // tiles retain fixed positions and independent gutters.
      const doorW=tw*(1-opening*.90);
      box(x,y,doorW,th,12,i%4===0?C.green:C.red);
      alpha(1-ease(opening/.55),()=>text(String(i+1).padStart(2,'0'),x+doorW/2,y+57,32,C.paper,800,'center',Math.max(1,doorW-24),42));
      alpha(1-ease(opening/.40),()=>circle(x+doorW-14,y+th/2,3,C.gold));
    }
  });
  const growth=ease((mix-.40)/.60);
  const startX=gridX+(focus%6)*(tw+gx)+tw/2;
  const startY=gridY+Math.floor(focus/6)*(th+gy)+th/2;
  const fx=lerp(startX,1366,growth),fy=lerp(startY,425,growth);
  const fw=lerp(tw,650,growth),fh=lerp(th,300,growth);
  box(fx-fw/2,fy-fh/2,fw,fh,lerp(12,25,growth),C.paper,C.line,2);
  alpha(1-ease((mix-.48)/.22),()=>{
    star(fx,fy-lerp(22,32,growth),lerp(17,27,growth),C.gold);
    text('15',fx,fy+lerp(21,34,growth),lerp(30,47,growth),C.red,800,'center',lerp(83,174,growth),54);
  });
  alpha(ease((mix-.72)/.28),()=>{
    caps('TODAY\'S CHRISTMAS OFFER',fx,fy-fh*.32,fw-78,C.green,22,'center');
    text('40% OFF',fx,fy-2,105,C.red,800,'center',fw-86,120);
    line(fx-fw/2+48,fy+fh*.227,fx+fw/2-48,fy+fh*.227,C.line,2);
    caps('SELECTED FESTIVE FAVORITES',fx,fy+fh*.373,fw-82,C.ink,18,'center');
  });
  // A compact advent display remains active below the offer. It appears only
  // after the expanding card has cleared its entire swept rectangle.
  alpha(ease((mix-.74)/.26),()=>{
    const miniX=1153,miniY=632,mw=61.36,mh=59.28,dx=8.32,dy=8.84;
    for(let i=0;i<24;i++) {
      const x=miniX+(i%6)*(mw+dx),y=miniY+Math.floor(i/6)*(mh+dy);
      box(x,y,mw,mh,7,C.paper,C.line,1.5);
      let o=0;
      if([3,9,20].includes(i)) {
        const q=(loopT/duration*2+i*.071)%1;
        o=pulse(q,.12,.23,.41,.52);
        star(x+mw/2,y+mh/2,13,C.gold);
      }
      const door=mw*(1-o*.90);
      box(x,y,door,mh,7,i===14?C.paper:(i%4===0?C.green:C.red));
      alpha(1-ease(o/.55),()=>text(String(i+1).padStart(2,'0'),x+door/2,y+mh/2,18,i===14?C.red:C.paper,800,'center',Math.max(1,door-14),24));
    }
  });
  sprig(1704,214,77,C.green,.28);
  sprig(989,851,74,C.green,-.18);
  accent(1778,886,19,.5);
  ctx.restore();
}
